// Doctor Calendar: my appointments grouped by day, with confirm/complete/no-show/cancel.
import { useCallback, useEffect, useMemo, useState } from 'react'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { threePortalApi, type AppointmentDto } from '../../services/apiClient'
import { FriendlyStatusBadge, extractErrorMessage, formatDateTime, formatDay } from '../family/threePortalShared'

type Action = 'confirm' | 'complete' | 'no-show' | 'cancel'

const nextActions: Record<AppointmentDto['status'], Action[]> = {
  Requested: ['confirm', 'cancel'],
  Confirmed: ['complete', 'no-show', 'cancel'],
  Completed: [],
  Cancelled: [],
  NoShow: [],
}

const actionLabel: Record<Action, string> = {
  confirm: 'Confirm',
  complete: 'Complete',
  'no-show': 'No-show',
  cancel: 'Cancel',
}

export function DoctorCalendarPage() {
  const [appointments, setAppointments] = useState<AppointmentDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const { data } = await threePortalApi.getDoctorAppointments()
      setAppointments(data)
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  const byDay = useMemo(() => {
    const groups = new Map<string, AppointmentDto[]>()
    for (const appointment of [...appointments].sort((a, b) => a.startsAt.localeCompare(b.startsAt))) {
      const key = appointment.startsAt.slice(0, 10)
      const list = groups.get(key) ?? []
      list.push(appointment)
      groups.set(key, list)
    }
    return [...groups.entries()].sort(([a], [b]) => a.localeCompare(b))
  }, [appointments])

  async function act(appointment: AppointmentDto, action: Action) {
    try {
      await threePortalApi.setAppointmentStatus(appointment.id, action)
      setMessage(`${appointment.memberDisplayName}'s appointment updated.`)
      await load()
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Appointment status could not be updated.'))
    }
  }

  if (status === 'loading') return <LoadingState label="Loading calendar" />
  if (status === 'error') return <ErrorState message="Calendar could not be loaded." onRetry={() => void load()} />

  return (
    <div className="page-stack">
      <header className="page-header">
        <div>
          <p className="eyebrow">Schedule</p>
          <h1>Calendar</h1>
        </div>
      </header>

      {message && <p role="status" className="status-banner">{message}</p>}

      {byDay.length === 0 ? (
        <EmptyState title="No appointments" message="Booked appointments will appear here, grouped by day." />
      ) : (
        byDay.map(([day, dayAppointments]) => (
          <section className="panel" key={day}>
            <h2>{formatDay(dayAppointments[0].startsAt)}</h2>
            <div className="table-scroll">
              <table>
                <thead>
                  <tr>
                    <th>Time</th>
                    <th>Member</th>
                    <th>Family</th>
                    <th>Reason</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {dayAppointments.map((appointment) => (
                    <tr key={appointment.id}>
                      <td>{formatDateTime(appointment.startsAt)}</td>
                      <td>{appointment.memberDisplayName}</td>
                      <td>{appointment.familyName}</td>
                      <td>{appointment.reason}</td>
                      <td><FriendlyStatusBadge status={appointment.status} /></td>
                      <td>
                        {nextActions[appointment.status].map((action) => (
                          <button
                            key={action}
                            className={`button ${action === 'cancel' ? 'button--danger' : 'button--secondary'}`}
                            type="button"
                            onClick={() => void act(appointment, action)}
                            style={{ marginRight: 6 }}
                          >
                            {actionLabel[action]}
                          </button>
                        ))}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        ))
      )}
    </div>
  )
}
